import {mkdir,writeFile,readFile,realpath} from 'node:fs/promises';import path from 'node:path';
import {database} from '../db.mjs';import {snapshot} from '../backup.mjs';import {storage} from '../storage.mjs';import {sha,demand} from '../security.mjs';
const requested=process.argv[2];if(!requested)throw Error('Provide a private directory outside the website.');await mkdir(requested,{recursive:true,mode:0o700});const base=await realpath(requested),site=path.resolve(import.meta.dirname,'../..');if(base===site||base.startsWith(site+path.sep))throw Error('Private directory required.');
const dir=path.join(base,'bundle-'+Date.now());await mkdir(dir,{mode:0o700});await mkdir(path.join(dir,'media'),{mode:0o700});const db=database();let backup;try{backup=await snapshot(db);}finally{await db.close();}
const refs=new Map();for(const f of backup.tables.legacy_files)refs.set(f.object_key,{key:f.object_key,expectedHash:f.sha256,bytes:Number(f.bytes)});
for(const v of [...backup.tables.versions,...(backup.tables.activity_assets||[])])for(const m of v.media)for(const field of ['originalKey','fullKey','thumbKey'])if(m[field])refs.set(m[field],{key:m[field],expectedHash:field==='originalKey'?m.sha256:field==='fullKey'?m.displayHash:null});
const store=storage(),items=[...refs.values()];let next=0;const files=[];
await Promise.all(Array.from({length:6},async()=>{while(next<items.length){const item=items[next++],bytes=await store.get(item.key,item.bytes||64*1024*1024),hash=sha(bytes);demand(!item.expectedHash||item.expectedHash===hash,409,'備份媒體雜湊不符。');const filename=sha(item.key);await writeFile(path.join(dir,'media',filename),bytes,{mode:0o600});demand(sha(await readFile(path.join(dir,'media',filename)))===hash,409,'本機副本核對失敗。');files.push({key:item.key,filename,sha256:hash,bytes:bytes.length});}}));
await writeFile(path.join(dir,'database.json'),JSON.stringify(backup),{mode:0o600});const manifest={format:'rib-backup-bundle-v1',databaseHash:backup.sha256,files:files.sort((a,b)=>a.key.localeCompare(b.key))};await writeFile(path.join(dir,'COMPLETE.json'),JSON.stringify(manifest),{mode:0o600,flag:'wx'});console.log(JSON.stringify({directory:dir,complete:true,objects:files.length,bytes:files.reduce((n,f)=>n+f.bytes,0),databaseHash:backup.sha256}));
